 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.goto('http://127.0.0.1:8000/cbse-mcq-page-settings.js');page.set_content('<main id="targets"></main>')
