 page.evaluate('''async()=>{const {showMCQAssignedCopies}=await import('./cbse-mcq-assigned-copies-view.js');window.printPaper={id:'QPE001',classId:'X',subjectId:'english',subjectName:'English',count:1,questions:[{id:'QE001',verbatim:true,stem:'Question\\nA) One\\nB) Two\\nC) Three\\nD) Four'}],copyAssignments:['X:a:one','X:a:two','X:b:three'].map((studentKey,i)=>({studentKey,token:String(i+1).repeat(32)}))};new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.matches?.('.mcq-layout-frame'))node.contentWindow.print=()=>{window.printed={pages:node.contentDocument.querySelectorAll('.paper-sheet').length,text:node.contentDocument.body.innerText,qr:node.contentDocument.querySelectorAll('[aria-label="Student paper QR"]').length};};}).observe(document.body,{childList:true});await showMCQAssignedCopies({id:'QPE001'},window.testCtx);}''')
